function ripple(button:Element,e:MouseEvent){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=button.getBoundingClientRect(),a=app.getBoundingClientRect(),layer=document.createElement('span'),wave=document.createElement('span'),size=Math.hypot(r.width,r.height)*2;layer.className='p-ripple-clip';wave.className='p-ripple-wave';layer.setAttribute('aria-hidden','true');Object.assign(layer.style,{left:r.left-a.left+'px',top:r.top-a.top+'px',width:r.width+'px',height:r.height+'px',borderRadius:getComputedStyle(button).borderRadius,color:getComputedStyle(button).color});Object.assign(wave.style,{width:size+'px',height:size+'px',left:(e.detail?e.clientX-r.left:r.width/2)-size/2+'px',top:(e.detail?e.clientY-r.top:r.height/2)-size/2+'px'});layer.append(wave);app.append(layer);setTimeout(()=>layer.remove(),600);}
