function savedRows(records=state.saved){return records.length?records.map(r=>'<div class="p-line-item"><span class="p-line-icon">'+icon('thermometer')+'</span><div class="p-detail">'+esc(r.input.name+' · '+r.input.room)+(r.building?' · '+r.building.rooms.length+' ambientes':'')+'<small>'+new Date(r.date).toLocaleString('es-AR')+' · '+esc(r.output.mode)+' · '+fmt(r.output.peak.total/1000)+' kW</small></div>'+btn('Abrir','data-open-calc="'+r.id+'"')+'</div>').join(''):'<p class="p-note">Todavía no guardaste versiones. El botón Guardar en proyecto conserva entradas, resultados y trazas.</p>';}
function field(label:string,path:string,d:Datum,opts:{min?:number;max?:number;step?:number}={}){return '<label class="p-field">'+esc(label)+'<input type="number" inputmode="decimal" data-field="'+path+'" value="'+d.value+'" step="'+(opts.step??.1)+'" '+(opts.min!==undefined?'min="'+opts.min+'"':'')+' '+(opts.max!==undefined?'max="'+opts.max+'"':'')+'><small>'+esc(d.unit)+' · '+esc(d.provenance)+'</small></label>';}
function selectField(label:string,path:string,value:string,options:[string,string][]){return '<label class="p-field">'+label+'<select data-choice="'+path+'">'+options.map(([v,l])=>'<option value="'+v+'" '+(v===value?'selected':'')+'>'+l+'</option>').join('')+'</select></label>';}
const steps=['Ubicación y clima','Envolvente y geometría','Cargas internas','Ventilación','Resultados'];
function labelPath(path:string){for(const item of [...state.input.surfaces,...state.input.windows]){if(path===item.id||path.startsWith(item.id+'.')||path.startsWith(item.id+'-'))return item.name+path.slice(item.id.length).replace(/-cts-rts/,' · CTS').replace(/-load-rts/,' · RTS');}return ({supply:'Impulsión',system:'Sistema',input:'Entradas','cargas-internas.rts':'Cargas internas · RTS'} as Record<string,string>)[path]||path;}
function methodMissing(path:string){if(path==='cargas-internas.rts'||path.endsWith('.rts'))return 'Tipología térmica del ambiente';if(path.endsWith('.solarRts'))return 'Respuesta solar del ambiente';if(path.endsWith('.cts'))return 'Construcción de '+labelPath(path.slice(0,-4));return labelPath(path);}
