function completeTask(id:string){const t=state.tasks.find(t=>t.id===id)!;t.lane=t.lane==='Resuelto'?'Por hacer':'Resuelto';const row=app.querySelector('[data-task-row="'+id+'"]') as HTMLTableRowElement;row.classList.toggle('done',t.lane==='Resuelto');row.classList.add('p-task-settling');row.cells[1].innerHTML=pill(t.lane,t.lane==='Resuelto'?'good':'accent');const button=row.querySelector('[data-task]') as HTMLButtonElement;button.classList.toggle('is-done',t.lane==='Resuelto');button.setAttribute('aria-pressed',String(t.lane==='Resuelto'));button.setAttribute('aria-label',(t.lane==='Resuelto'?'Reabrir':'Completar')+' '+t.title);button.innerHTML=t.lane==='Resuelto'?icon('check'):'';const metrics=app.querySelectorAll('.p-metric-number');if(metrics[1])metrics[1].textContent=String(state.tasks.filter(t=>t.lane!=='Resuelto').length);icons();setTimeout(()=>row.classList.remove('p-task-settling'),650);log((t.lane==='Resuelto'?'Completada: ':'Reabierta: ')+t.title);scheduleStore();}
