function showTrace(id:string){if(!output){toast('No hay resultado válido para inspeccionar.');return;}const t=output.trace.find(t=>t.id===id);if(!t){toast('Esta magnitud no se calculó con las entradas actuales.');return;}const value=Array.isArray(t.result)?t.result.length===24?t.result[state.selectedHour]:t.result.join(', '):t.result,vars=t.variables;
 const audit=vars.K&&vars.A&&vars.delta?'<section class="p-audit-card"><div class="p-section-label">DESCOMPOSICIÓN AUDITABLE</div><div class="p-audit-grid">'+[
  ['K usado',vars.K],
  ['Área',vars.A],
  ...(vars.deltaTabla?[['Δt tabla',vars.deltaTabla] as const]:[]),
  ...(vars.correccionDiseno?[['Corrección ΔT diseño',vars.correccionDiseno] as const]:[]),
  ['Δt usado',vars.delta]
 ].map(([label,v])=>'<div><small>'+esc(label)+'</small><strong>'+esc(typeof v.value==='number'?fmt(v.value,5):v.value)+' '+esc(v.unit)+'</strong><span>'+esc(v.source)+'</span></div>').join('')+'</div><div class="p-audit-result"><span>Resultado</span><strong>'+esc(typeof value==='number'?fmt(value,5):value??'No disponible')+' '+esc(t.unit)+'</strong></div></section>':'';
 drawer('¿Por qué da esta carga?',pill(t.engineVersion,'accent')+' '+pill(t.unit)+'<h2 style="margin-top:18px">'+esc(t.label)+'</h2><div class="p-formula">'+esc(t.equation)+'</div>'+audit+(!audit?'<div class="p-result-value">'+esc(typeof value==='number'?fmt(value,5):value??'No disponible')+' <span class="p-muted">'+esc(t.unit)+'</span></div>':'')+'<p class="p-note"><strong>Fuente:</strong> '+esc(t.source)+(Array.isArray(t.result)&&t.result.length===24?' · hora '+state.selectedHour+':00':'')+'</p><details class="p-advanced" '+(audit?'':'open')+'><summary>Variables y procedencia</summary>'+Object.entries(t.variables).map(([name,v])=>'<div class="p-var"><div class="p-var-head"><strong>'+esc(name)+'</strong>'+pill(v.provenance)+'</div><code>'+esc(Array.isArray(v.value)?JSON.stringify(v.value):v.value)+' '+esc(v.unit)+'</code><small>'+esc(v.source)+'</small></div>').join('')+'</details>'+t.warnings.map(w=>'<p class="p-note">'+esc(w)+'</p>').join('')+(id.startsWith('component-particiones-')?'<h3>Fórmulas de las paredes compartidas</h3><div class="p-actions">'+roomPartitions().map(p=>btn(esc(p.name),'data-trace="partition-'+esc(p.id)+'"')).join('')+'</div>':''));bindResultActions();}

function traceList(){if(!output)return;drawer('Trazabilidad del cálculo','<label class="p-field">Buscar ecuación<input data-trace-query placeholder="Ej.: humedad, muro, solar, ventilación"></label><div data-trace-list></div>');const input=app.querySelector('[data-trace-query]') as HTMLInputElement,container=app.querySelector('[data-trace-list]')!;const update=()=>{const q=input.value.toLowerCase();const traces=[...new Map(output!.trace.map(t=>[t.id,t])).values()].filter(t=>(t.label+' '+t.id+' '+t.equation).toLowerCase().includes(q));container.innerHTML=traces.slice(0,70).map(t=>'<button class="p-library-item" data-trace="'+esc(t.id)+'">'+esc(t.label)+'<small>'+esc(t.source)+' · '+esc(t.unit)+'</small></button>').join('')+'<p class="p-note">'+traces.length+' trazas coincidentes · se muestran hasta 70; todas están en el JSON.</p>';bindResultActions();};input.oninput=update;update();input.focus();}
function search(){drawer('Buscar en THERMABOT','<label class="p-field">Proyecto o cálculo<input data-query placeholder="Nombre, establecimiento o ambiente"></label><div data-search-list></div>');const input=app.querySelector('[data-query]') as HTMLInputElement,list=app.querySelector('[data-search-list]')!;const update=()=>{const q=input.value.toLowerCase();list.innerHTML=state.projects.filter(p=>(p.name+' '+p.place).toLowerCase().includes(q)).map(p=>'<button class="p-library-item" data-project="'+p.id+'">'+esc(p.name)+'<small>'+esc(p.place)+'</small></button>').join('')+state.saved.filter(r=>(r.input.name+' '+r.input.room).toLowerCase().includes(q)).map(r=>'<button class="p-library-item" data-open-calc="'+r.id+'">'+esc(r.input.name+' · '+r.input.room)+'<small>Cálculo guardado</small></button>').join('');bind();};input.oninput=update;update();input.focus();}
function newProject(){drawer('Nuevo proyecto','<label class="p-field">Nombre<input data-project-name placeholder="Nombre de la obra"></label><label class="p-field" style="margin-top:15px">Establecimiento / cliente<input data-project-place placeholder="Cliente"></label><div class="p-save-bar">'+btn('Crear proyecto','data-create-project','primary')+'</div>');app.querySelector('[data-create-project]')!.addEventListener('click',()=>{const name=(app.querySelector('[data-project-name]') as HTMLInputElement).value.trim(),place=(app.querySelector('[data-project-place]') as HTMLInputElement).value.trim();if(!name){toast('Ingresá un nombre.');return;}const p={id:crypto.randomUUID(),name,place:place||'Sin establecimiento',system:'Instalación HVAC',progress:0,status:'Ingeniería'};state.projects.push(p);state.projectId=p.id;log('Proyecto creado: '+name);route('Proyecto');});}
