function hourlyEditor(kind:string){const c=state.input.climate;const paths=kind==='climate'?['climate.temperature','climate.rh','climate.radiation.dni','climate.radiation.dhi']:kind==='sunlit'?['windows.0.sunlitFraction']:['internals.people.schedule','internals.lights.schedule','internals.equipment.schedule'];const names=kind==='climate'?['Exterior °C','RH exterior %','DNI W/m²','DHI W/m²']:kind==='sunlit'?['Fracción soleada 0…1']:['Personas 0…1','Luces 0…1','Equipos 0…1'];drawer('Perfiles horarios','<p class="p-note">Horarios solares 00–23; el perfil de verano Quadri evalúa 06–23. La radiación solar tabulada por vidrios termina a las 18 h. Fracciones ingresadas, sin curvas de uso automáticas.</p>'+paths.map((path,j)=>'<details '+(j===0?'open':'')+' class="p-advanced"><summary>'+names[j]+'</summary><div class="p-hour-grid">'+(at(path) as Datum[]).map((d,h)=>'<label class="p-field">'+String(h).padStart(2,'0')+':00<input type="number" data-hour-path="'+path+'" data-hour="'+h+'" step=".1" value="'+d.value+'"></label>').join('')+'</div></details>').join('')+'<div class="p-save-bar">'+btn('Aplicar perfiles','data-apply-hours','primary')+'</div>');app.querySelector('[data-apply-hours]')!.addEventListener('click',()=>{try{const next=clone(state.input);app.querySelectorAll('[data-hour-path]').forEach(el=>{const field=el as HTMLInputElement,path=field.dataset.hourPath!,keys=path.split('.');let target:any=next;keys.forEach(k=>target=target[k]);const hour=Number(field.dataset.hour);target[hour]=datum(field.valueAsNumber,target[hour].unit,'ingresado','Perfil horario manual · '+path+' · '+hour+':00');});calculateRoom(next);state.input=next;if(kind==='climate')shareOutdoorClimate();closeLayer();recalc();render();scheduleStore();toast('Perfil aplicado',true);}catch(e){toast((e as Error).message);}});}
