function removeEnvelope(kind:'surface'|'window',id:string){if(kind==='surface'&&roomPartitions().some(p=>p.roomAId===state.input.id?p.surfaceAId===id:p.surfaceBId===id)){toast('El muro pertenece a una pared compartida. Eliminá primero esa vinculación.');return;}if(kind==='surface'&&state.input.windows.some(w=>w.parentId===id)){toast('Reubicá o eliminá primero las ventanas de este cerramiento.');return;}const list=kind==='surface'?state.input.surfaces:state.input.windows,item=list.find(x=>x.id===id);if(!item)return;removedEnvelope={roomId:state.input.id,kind,item:clone(item)};if(kind==='surface')state.input.surfaces=state.input.surfaces.filter(x=>x.id!==id);else state.input.windows=state.input.windows.filter(x=>x.id!==id);log('Cerramiento eliminado: '+item.name);recalc();render();scheduleStore();toast('Eliminado. Podés deshacerlo desde Geometría.',true);}
function undoEnvelope(){if(!removedEnvelope||removedEnvelope.roomId!==state.input.id)return;const last=removedEnvelope;if(last.kind==='surface')state.input.surfaces.push(last.item as Surface);else{const w=last.item as WindowSurface;if(!state.input.surfaces.some(s=>s.id===w.parentId)){toast('Restaurá primero el cerramiento de la ventana.');return;}state.input.windows.push(w);}removedEnvelope=null;recalc();render();scheduleStore();}
function buildingSummary(){try{const result=calculateBuilding(buildingInput());drawer('Resumen del edificio','<p class="p-note">'+esc(result.input.name)+' · '+result.results.length+' ambientes · '+fmt(result.area,1)+' m² · '+fmt(result.volume,1)+' m³</p><div class="p-building-total"><span>Pico simultáneo de cargas de ambientes</span><strong>'+fmt(result.peak.total/1000)+' kW</strong><small>Hora '+result.peak.hour+':00 · sensible '+fmt(result.peak.sensible/1000)+' · latente '+fmt(result.peak.latent/1000)+' kW</small></div><p class="p-note">Se suman las cargas de la misma hora, no los picos individuales. El aire exterior de una central se verifica aparte.</p>'+buildingPartitionsHtml(result.input)+'<div class="p-building-rooms">'+result.results.map(r=>'<button class="p-library-item" data-summary-room="'+esc(r.input.id)+'"><strong>'+esc(r.input.room)+'</strong><small>'+fmt(r.input.geometry.length.value*r.input.geometry.width.value,1)+' m² · '+r.input.surfaces.length+' cerramientos · '+r.input.windows.length+' ventanas</small><small>Pico propio '+fmt(r.peak.total/1000)+' kW · '+r.peak.hour+':00 · Aporte al pico conjunto '+fmt(r.hours.find(h=>h.hour===result.peak.hour)!.total/1000)+' kW</small></button>').join('')+'</div><details class="p-advanced"><summary>Perfil conjunto de horas calculadas</summary><div class="p-building-hours">'+result.hours.map(h=>'<div><span>'+String(h.hour).padStart(2,'0')+':00</span><meter min="0" max="'+Math.max(...result.hours.map(h=>h.total),1)+'" value="'+Math.max(0,h.total)+'"></meter><span>'+fmt(h.total/1000)+' kW</span></div>').join('')+'</div></details><div class="p-save-bar">'+btn('Exportar edificio JSON','data-export-building','primary')+btn('Importar ambiente JSON','data-import-room')+'</div>');app.querySelectorAll('[data-summary-room]').forEach(el=>(el as HTMLElement).onclick=()=>activateRoom((el as HTMLElement).dataset.summaryRoom!));(app.querySelector('[data-export-building]') as HTMLElement).onclick=()=>download('THERMABOT-Quadri-edificio.json',JSON.stringify({application:'THERMABOT-building',schemaVersion:1,date:new Date().toISOString(),building:result.input,reviews:projectReviews(),summary:{hours:result.hours,peak:result.peak,area:result.area,volume:result.volume,trace:result.trace}},null,2),'application/json');(app.querySelector('[data-import-room]') as HTMLElement).onclick=()=>importJson(importRoomFile);}catch(e){drawer('Resumen del edificio','<div class="p-warnings p-error" role="alert">'+esc((e as Error).message)+'</div><p class="p-note">Corregí el ambiente indicado antes de guardar o exportar el edificio completo.</p>');}}
function openSavedCalculation(id:string){const r=state.saved.find(x=>x.id===id)!;checkpointRoom();if(r.building){state.partitions=state.partitions.filter(p=>p.projectId!==r.building!.projectId).concat(clone(r.building.partitions||[]));state.rooms=state.rooms.filter(x=>x.projectId!==r.building!.projectId).concat(r.building.rooms.map(x=>enableQuadri(migrateEnvelope(x))));state.input=state.rooms.find(x=>x.id===r.input.id)||state.rooms.find(x=>x.projectId===r.building!.projectId)!;}else{state.input=enableQuadri(migrateEnvelope(clone(r.input)));checkpointRoom();}if(r.reviews)for(const room of r.building?.rooms||[r.input])state.reviews[room.id]=clone(r.reviews[room.id]||{});state.projectId=state.input.projectId;state.step=4;recalc();route('Balance térmico');}
function importRoomFile(data:any){const original=data.input||data;if(original.schemaVersion!==2)throw Error('Archivo de ambiente incompatible');const next=enableQuadri(migrateEnvelope(original));next.projectId=state.input.projectId;next.id=crypto.randomUUID();const c=state.input.climate;next.climate.location=clone(c.location);next.climate.temperature=clone(c.temperature);next.climate.rh=clone(c.rh);next.climate.radiation=clone(c.radiation);if(c.pressure)next.climate.pressure=clone(c.pressure);else delete next.climate.pressure;for(const key of ['season','city','solarBasis','dailyRange','outdoorSummer','rhSummer','outdoorWinter','rhWinter'] as const)(next.quadri as any)[key]=clone(state.input.quadri![key]);calculate(next);state.rooms.push(next);log('Ambiente importado: '+next.room);activateRoom(next.id);toast('Ambiente importado sin paredes compartidas; vinculalo en Geometría. Para recuperar todos los vínculos, importá el edificio.',true);}
function importBackup(data:any){if(data.application==='THERMABOT-building'&&data.schemaVersion===1){const building=clone(data.building) as BuildingInput;building.rooms=building.rooms.map(enableQuadri);calculateBuilding(building);for(const room of building.rooms){if(state.rooms.some(r=>r.projectId!==building.projectId&&r.id===room.id)){const oldId=room.id;room.id=crypto.randomUUID();for(const p of building.partitions||[]){if(p.roomAId===oldId)p.roomAId=room.id;if(p.roomBId===oldId)p.roomBId=room.id;}}}if(projectRooms(building.projectId).length&&!confirm('Importar reemplaza los ambientes actuales de este proyecto. ¿Continuar?'))return;checkpointRoom();if(!state.projects.some(p=>p.id===building.projectId))state.projects.push({id:building.projectId,name:building.name,place:'Importado',system:'Instalación HVAC',progress:0,status:'Ingeniería'});state.partitions=state.partitions.filter(p=>p.projectId!==building.projectId).concat(clone(building.partitions||[]));state.rooms=state.rooms.filter(r=>r.projectId!==building.projectId).concat(clone(building.rooms));for(const room of building.rooms)state.reviews[room.id]=clone(data.reviews?.[room.id]||{});state.input=state.rooms.find(r=>r.projectId===building.projectId)!;state.projectId=building.projectId;recalc();route('Balance térmico');toast('Edificio importado',true);return;}
 if(!['THERMABOT-building-trial','THERMABOT-v2-trial'].includes(data.application)||!data.state||![2,3].includes(data.state.version))throw Error('No es un respaldo compatible. Para un ambiente usá Importar ambiente JSON en Resumen edificio.');if(!Array.isArray(data.state.projects)||!Array.isArray(data.state.saved))throw Error('Respaldo incompleto: faltan proyectos o versiones');validateTree(data.state);const incoming={...clone(initial),...data.state,version:3};incoming.input=enableQuadri(migrateEnvelope(incoming.input));incoming.rooms=Array.isArray(data.state.rooms)?data.state.rooms.map((r:ProjectInput)=>enableQuadri(migrateEnvelope(r))):[incoming.input];incoming.trashedRooms=data.state.trashedRooms||[];incoming.partitions=data.state.partitions||[];for(const project of incoming.projects){const rooms=incoming.rooms.filter((r:ProjectInput)=>r.projectId===project.id);if(rooms.length)calculateBuilding({schemaVersion:1,projectId:project.id,name:project.name,rooms,partitions:incoming.partitions.filter((p:SharedPartition)=>p.projectId===project.id)});}if(new Set(incoming.rooms.map((r:ProjectInput)=>r.id)).size!==incoming.rooms.length)throw Error('Respaldo con ambientes duplicados');incoming.saved.forEach((r:any)=>{calculate(r.input);if(r.building)calculateBuilding(r.building);});calculate(incoming.input);if(state.saved.length&&!confirm('Importar reemplaza el espacio de esta prueba. ¿Continuar?'))return;state=incoming;state.reviews??={};state.waterResults??={};state.saved=state.saved.map(r=>({...r,output:{mode:r.output.mode,peak:r.output.peak,engineVersion:"quadri-preview.2",tracePolicy:"Trazas regenerables desde entradas completas y motor versionado"} as any}));checkpointRoom();recalc();store();render();toast('Respaldo recuperado',true);}
function bindBuilding(){app.querySelectorAll('[data-water]').forEach(el=>(el as HTMLElement).onclick=waterDrawer);bindPartitions();bindGeometry();app.querySelectorAll('[data-add-room]').forEach(el=>(el as HTMLElement).onclick=newRoomDialog);app.querySelectorAll('[data-duplicate-room]').forEach(el=>(el as HTMLElement).onclick=duplicateRoom);app.querySelectorAll('[data-archive-room]').forEach(el=>(el as HTMLElement).onclick=archiveRoom);app.querySelectorAll('[data-archived-rooms]').forEach(el=>(el as HTMLElement).onclick=archivedRooms);app.querySelectorAll('[data-building-summary]').forEach(el=>(el as HTMLElement).onclick=buildingSummary);const select=app.querySelector('[data-room-select]') as HTMLSelectElement|null;if(select)select.onchange=()=>activateRoom(select.value);app.querySelectorAll('[data-add-surface]').forEach(el=>(el as HTMLElement).onclick=()=>envelopeEditor('surface',undefined,(el as HTMLElement).dataset.addSurface!));app.querySelectorAll('[data-add-window]').forEach(el=>(el as HTMLElement).onclick=()=>envelopeEditor('window'));app.querySelectorAll('[data-edit-surface]').forEach(el=>(el as HTMLElement).onclick=()=>envelopeEditor('surface',(el as HTMLElement).dataset.editSurface!));app.querySelectorAll('[data-edit-window]').forEach(el=>(el as HTMLElement).onclick=()=>envelopeEditor('window',(el as HTMLElement).dataset.editWindow!));app.querySelectorAll('[data-delete-surface]').forEach(el=>(el as HTMLElement).onclick=()=>removeEnvelope('surface',(el as HTMLElement).dataset.deleteSurface!));app.querySelectorAll('[data-delete-window]').forEach(el=>(el as HTMLElement).onclick=()=>removeEnvelope('window',(el as HTMLElement).dataset.deleteWindow!));app.querySelectorAll('[data-undo-envelope]').forEach(el=>(el as HTMLElement).onclick=undoEnvelope);}


function projectPartitions(projectId=state.input.projectId){return (state.partitions||[]).filter(p=>p.projectId===projectId);}
function roomPartitions(roomId=state.input.id){return projectPartitions().filter(p=>p.roomAId===roomId||p.roomBId===roomId);}
function calculateRoom(source:ProjectInput,partitions?:SharedPartition[]):Calculation {
 const building=buildingInput();building.rooms=building.rooms.map(r=>r.id===source.id?enableQuadri(source):enableQuadri(r));if(partitions)building.partitions=partitions;
 return calculate(enableQuadri(source),resolvePartitions(building).get(source.id)||[]);
}
function partitionRows(){const links=roomPartitions(),rooms=projectRooms();return '<div class="p-envelope-heading"><h3>Ambientes contiguos</h3>'+btn('+ Pared compartida','data-add-partition '+(rooms.length<2?'disabled':''))+'</div><p class="p-note">Elegí dos muros que se tocan. La superficie compartida se descuenta del exterior en ambos ambientes; el resto del muro conserva su exposición exterior. U interior se ingresa con su fuente.</p>'+(links.length?links.map(p=>{const ownA=p.roomAId===state.input.id,other=rooms.find(r=>r.id===(ownA?p.roomBId:p.roomAId)),ti=numberOf(state.input.quadri!.season==='invierno'?state.input.quadri!.indoorWinter:state.input.climate.indoorTemperature,'°C'),tj=other?numberOf(other.quadri?.season==='invierno'?other.quadri.indoorWinter:other.climate.indoorTemperature,'°C'):NaN,q=p.u.value*p.area.value*(state.input.quadri!.season==='invierno'?ti-tj:tj-ti);return '<article class="p-envelope-row"><span class="p-line-icon">'+icon('arrow-left-right')+'</span><div class="p-detail"><strong>'+esc(p.name)+'</strong><small>'+esc(state.input.room)+' ↔ '+esc(other?.room||'Ambiente pendiente')+' · '+fmt(p.area.value)+' m² · U '+fmt(p.u.value)+'</small><small>'+fmt(ti,1)+' / '+fmt(tj,1)+' °C · '+(q>0?'+':'')+fmt(q,1)+' W en este ambiente</small><small>Régimen estacionario · sin paso de aire ni humedad</small></div><div class="p-envelope-actions">'+btn('Editar','data-edit-partition="'+esc(p.id)+'" aria-label="Editar '+esc(p.name)+'"')+btn(icon('trash-2'),'data-delete-partition="'+esc(p.id)+'" aria-label="Eliminar '+esc(p.name)+'"','ghost')+'</div></article>';}).join(''):'<p class="p-empty-envelope">'+(rooms.length<2?'Agregá otro ambiente para vincular una pared compartida.':'Sin paredes compartidas. Los muros actuales se calculan como exteriores.')+'</p>')+(removedPartition?.projectId===state.input.projectId?btn('Deshacer eliminación de pared compartida','data-undo-partition'):'');}
let removedPartition:SharedPartition|null=null;
function bindPartitions(){app.querySelectorAll('[data-add-partition]').forEach(el=>(el as HTMLElement).onclick=()=>partitionEditor());app.querySelectorAll('[data-edit-partition]').forEach(el=>(el as HTMLElement).onclick=()=>partitionEditor((el as HTMLElement).dataset.editPartition));app.querySelectorAll('[data-delete-partition]').forEach(el=>(el as HTMLElement).onclick=()=>{const id=(el as HTMLElement).dataset.deletePartition!,p=projectPartitions().find(p=>p.id===id)!;removedPartition=clone(p);state.partitions=state.partitions.filter(p=>p.id!==id||p.projectId!==state.input.projectId);log('Pared compartida eliminada: '+p.name);recalc();render();scheduleStore();toast('Vinculación eliminada; ambas superficies vuelven a ser exteriores. Podés deshacer.',true);});app.querySelectorAll('[data-undo-partition]').forEach(el=>(el as HTMLElement).onclick=()=>{if(!removedPartition)return;try{calculateRoom(state.input,[...projectPartitions(),removedPartition]);state.partitions.push(removedPartition);removedPartition=null;recalc();render();scheduleStore();toast('Pared compartida restaurada',true);}catch(e){toast((e as Error).message);}});}
function partitionEditor(id?:string){
 const old=projectPartitions().find(p=>p.id===id),rooms=projectRooms(),draft:SharedPartition=old?clone(old):{id:crypto.randomUUID(),projectId:state.input.projectId,name:'Pared compartida',roomAId:state.input.id,surfaceAId:'',roomBId:rooms.find(r=>r.id!==state.input.id)?.id||'',surfaceBId:'',area:datum(0,'m²'),u:datum(0,'W/(m²·K)'),model:'estacionario'};
 const selectRooms=(key:'roomAId'|'roomBId')=>'<label class="p-field">'+(key==='roomAId'?'Ambiente A':'Ambiente B')+'<select data-part="'+key+'">'+rooms.map(r=>'<option value="'+esc(r.id)+'" '+(r.id===draft[key]?'selected':'')+'>'+esc(r.room)+'</option>').join('')+'</select></label>';
 drawer(old?'Editar pared compartida':'Vincular ambientes contiguos','<label class="p-field">Nombre de la pared compartida<input data-part="name" value="'+esc(draft.name)+'"></label><div class="p-form-grid" style="margin-top:16px">'+selectRooms('roomAId')+selectRooms('roomBId')+'<label class="p-field">Muro del ambiente A<select data-part="surfaceAId"></select></label><label class="p-field">Muro del ambiente B<select data-part="surfaceBId"></select></label><label class="p-field">Superficie compartida<input type="number" min="0" step=".1" data-part="area" value="'+(old?draft.area.value:'')+'" placeholder="Ingresá el área real"><small>m² · se descuenta del exterior en ambos muros</small></label><label class="p-field">U de la partición interior<input type="number" min="0" step=".01" data-part="u" value="'+(old?draft.u.value:'')+'" placeholder="Ingresá el U verificado"><small>W/(m²·K) · incluye las películas interiores</small></label></div><label class="p-field" style="margin-top:16px">Fuente de U<input data-part="source" value="'+(old?esc(draft.u.source):'')+'" placeholder="Ej.: cálculo por capas o ficha técnica"></label><p class="p-note">Este vínculo representa una pared física. Verificá que ambos muros se toquen en el plano. U·A·ΔT estacionario; condiciones interiores de diseño constantes durante 24 h. No simula inercia del muro ni flujo de aire entre ambientes.</p><div class="p-editor-feedback" role="status" data-part-preview></div><div class="p-save-bar">'+btn(old?'Aplicar cambios':'Vincular ambientes','data-part-apply','primary')+'</div>');
 const field=(key:string)=>app.querySelector('[data-part="'+key+'"]') as HTMLInputElement|HTMLSelectElement,apply=app.querySelector('[data-part-apply]') as HTMLButtonElement,feedback=app.querySelector('[data-part-preview]')!;
 const hosts=()=>{for(const side of ['A','B'] as const){const room=rooms.find(r=>r.id===draft['room'+side+'Id']),key=('surface'+side+'Id') as 'surfaceAId'|'surfaceBId',select=field(key) as HTMLSelectElement;select.innerHTML=(room?.surfaces.filter(s=>s.kind!=='roof'&&s.tilt.value===90)||[]).map(s=>'<option value="'+esc(s.id)+'">'+esc(s.name)+'</option>').join('');if(Array.from(select.options).some(o=>o.value===draft[key]))select.value=draft[key];draft[key]=select.value;}};
 const candidates=()=>projectPartitions().filter(p=>p.id!==draft.id).concat(clone(draft));
 const preview=()=>{try{if(!draft.name.trim())throw Error('Ingresá el nombre de la pared');if(!draft.u.source.trim())throw Error('Ingresá la fuente de U; no se usan factores genéricos');const building=buildingInput();building.partitions=candidates();const links=resolvePartitions(building),a=rooms.find(r=>r.id===draft.roomAId)!,b=rooms.find(r=>r.id===draft.roomBId)!,qa=draft.u.value*draft.area.value*(numberOf(b.climate.indoorTemperature,'°C')-numberOf(a.climate.indoorTemperature,'°C'));calculateRoom(state.input,building.partitions);feedback.classList.remove('is-error');feedback.innerHTML='<strong>'+esc(a.room)+': '+(qa>0?'+':'')+fmt(qa,1)+' W</strong><br>'+esc(b.room)+': '+(-qa>0?'+':'')+fmt(-qa,1)+' W<br>Σ intercambio interno = 0 W. Se descuenta '+fmt(draft.area.value)+' m² del exterior de cada muro.';apply.disabled=false;}catch(e){feedback.classList.add('is-error');feedback.textContent=(e as Error).message;apply.disabled=true;}};
 app.querySelectorAll('[data-part]').forEach(el=>{const f=el as HTMLInputElement|HTMLSelectElement;const update=()=>{const key=f.dataset.part!;if(key==='area'||key==='u'){draft[key]={value:(f as HTMLInputElement).valueAsNumber,unit:key==='area'?'m²':'W/(m²·K)',provenance:'ingresado',source:key==='area'?'Superficie compartida ingresada por el usuario':field('source').value.trim()};}else if(key==='source')draft.u.source=f.value.trim();else (draft as any)[key]=f.value;if(key==='roomAId'||key==='roomBId')hosts();preview();};if(f.tagName==='SELECT')f.onchange=update;else f.oninput=update;});
 apply.onclick=()=>{if(apply.disabled)return;try{calculateRoom(state.input,candidates());state.partitions=state.partitions.filter(p=>p.id!==draft.id||p.projectId!==draft.projectId).concat(clone(draft));log('Pared compartida '+(old?'actualizada: ':'creada: ')+draft.name);closeLayer();recalc();render();scheduleStore();toast('Ambientes vinculados. Balance y superficies exteriores actualizados.',true);}catch(e){toast((e as Error).message);}};
 hosts();preview();
}
function buildingPartitionsHtml(building:BuildingInput){return '<details class="p-advanced"><summary>Paredes compartidas · '+(building.partitions||[]).length+'</summary><p class="p-note">Cada transferencia interna se suma en un ambiente y se resta en el otro. Su suma en el edificio es cero; las áreas vinculadas dejan de tener exposición exterior.</p>'+(building.partitions||[]).map(p=>{const a=building.rooms.find(r=>r.id===p.roomAId)!,b=building.rooms.find(r=>r.id===p.roomBId)!,q=p.u.value*p.area.value*(numberOf(b.climate.indoorTemperature,'°C')-numberOf(a.climate.indoorTemperature,'°C'));return '<div class="p-line-item"><div class="p-detail"><strong>'+esc(p.name)+'</strong><small>'+esc(a.room)+' ↔ '+esc(b.room)+' · '+fmt(p.area.value)+' m²</small><small>'+fmt(q,1)+' W en '+esc(a.room)+' / '+fmt(-q,1)+' W en '+esc(b.room)+'</small></div></div>';}).join('')+'</details>';}
function pdfPartitions(line:(text:string,strong?:boolean)=>void){const links=roomPartitions();if(!links.length)return;line('PAREDES COMPARTIDAS ENTRE AMBIENTES',true);const resolved=resolvePartitions(buildingInput()).get(state.input.id)||[];for(const p of resolved){const q=p.u.value*p.area.value*(numberOf(p.adjacentTemperature,'°C')-numberOf(state.input.climate.indoorTemperature,'°C'));line(p.name+' | adyacente '+p.adjacentRoomName+' | '+fmt(p.area.value)+' m2 | U '+fmt(p.u.value)+' | '+fmt(q,1)+' W');line('Fuente U: '+p.u.source+' | q=U*A*(Tadyacente-Tinterior), regimen estacionario');line('Superficie descontada del exterior de '+(state.input.surfaces.find(s=>s.id===p.surfaceId)?.name||p.surfaceId));}line('Sin almacenamiento termico en el muro ni intercambio de aire/humedad.');}

function quadriHour(){if(!output)return;const v=output.quadri!.hours.find(h=>h.hour===state.selectedHour)||output.quadri!.peak,el=app.querySelector('[data-quadri-hour]');if(el)el.innerHTML='<div class="p-form-grid">'+(output.quadri!.season==='verano'?[['QSi',v.QSi],['QLi',v.QLi],['QTi',v.QTi],['QTe',v.QTe],['QT',v.QT],['QST',v.QST],['FCS',v.FCS],['PRA',v.PRA],['PRS',v.PRS]]:[['Qo',v.Qo],['QSi',v.Qt],['QTe',v.QTe],['QT',v.QT]]).map(([id,value])=>'<button class="p-library-item" data-trace="quadri-'+id+'-'+v.hour+'">'+(id==='QSi'&&output!.quadri!.season==='invierno'?'Qt':id)+'<small>'+fmt(value as number|null,id==='FCS'?3:id==='PRA'||id==='PRS'?1:0)+' '+(id==='FCS'?'':id==='PRA'||id==='PRS'?'°C':'kcal/h')+'</small></button>').join('')+'</div>';const check=app.querySelector('[data-equipment-check]'),at=output.quadri!.hours.find(h=>h.hour===output!.systemPeak.hour)!;if(check){const selection=at.selection;const worst=output.quadri!.hours;const total=selection&&worst.every(h=>h.selection!.total),sensible=selection&&worst.every(h=>h.selection!.sensible),flow=selection&&worst.every(h=>h.selection!.flow);check.innerHTML='<p class="p-note">'+(!selection?'Cargá una ficha para comparar.':!selection.checked?'Ficha incompleta: falta fuente, capacidad sensible o caudal.':total&&sensible&&flow?'Cubre total, sensible y caudal del intervalo calculado. Verificá condiciones de la ficha.':'No cubre: '+[!total?'total':'',!sensible?'sensible':'',!flow?'caudal':''].filter(Boolean).join(', '))+'</p>';}bindResultActions();}

function appliances(){drawer('Equipos · Cuadro 7-III','<p class="p-note">Estimaciones del manual (p.110), editables. Agregá la potencia de cada equipo; el dato medido del equipo real tiene prioridad.</p>'+QUADRI_APPLIANCES.map(x=>'<button class="p-library-item" data-appliance="'+x[0]+'">'+esc(x[1])+'<small>Agregar '+x[2]+' W al total</small></button>').join(''));app.querySelectorAll('[data-appliance]').forEach(el=>(el as HTMLElement).onclick=()=>{const row=QUADRI_APPLIANCES.find(x=>x[0]===(el as HTMLElement).dataset.appliance)!;state.input.internals.equipment.inputPower=datum(state.input.internals.equipment.inputPower.value+row[2],'W','biblioteca','Cuadro 7-III, p.110 · '+row[1]+' agregado al total');closeLayer();changed();render();});}

function bindQuadri(){app.querySelectorAll('[data-appliances]').forEach(el=>(el as HTMLElement).onclick=appliances);app.querySelectorAll('[data-quadri-example]').forEach(el=>(el as HTMLElement).onclick=()=>{const sample=quadriReference(state.input.quadri!.season);checkpointRoom();let target=state.projects.find(p=>p.id===sample.projectId);if(!target){target={id:sample.projectId,name:'Caso resuelto de Quadri',place:'Ejemplo del manual',system:'Oficina · 54 m²',progress:0,status:'Ingeniería'};state.projects.push(target);}const old=state.rooms.findIndex(r=>r.id===sample.id);if(old<0)state.rooms.push(sample);else state.rooms[old]=sample;state.input=sample;state.projectId=sample.projectId;state.step=4;state.selectedHour=15;recalc();render();scheduleStore();toast('Ejemplo cargado en un proyecto de prueba separado. Elegí las 15 h para comparar la planilla del libro.',true);});}

function shareQuadriClimate(){checkpointRoom();const q=state.input.quadri!;for(const r of projectRooms()){if(r.id===state.input.id)continue;r.quadri??=quadriDefaults();for(const key of ['season','city','solarBasis','dailyRange','outdoorSummer','rhSummer','outdoorWinter','rhWinter'] as const)(r.quadri as any)[key]=clone(q[key]);}shareOutdoorClimate();}


function seasonButtons(){return '<div class="p-season-switch" role="group" aria-label="Estación del balance">'+(['verano','invierno'] as const).map(v=>btn(v==='verano'?'Verano':'Invierno','data-season="'+v+'" aria-pressed="'+(state.input.quadri!.season===v)+'"',state.input.quadri!.season===v?'primary':'ghost')).join('')+'</div>';}
function reviewsFor(r:ProjectInput){return roomReview(r,state.reviews[r.id],projectPartitions().filter(p=>p.roomAId===r.id||p.roomBId===r.id));}
function reviewStatus(){const n=reviewsFor(state.input).filter(x=>!x.reviewed).length;return btn(n?n+' bloques por revisar':'Carga revisada','data-review-room',n?'ghost':'primary');}
function projectReviews(){return Object.fromEntries(projectRooms().map(r=>[r.id,clone(state.reviews[r.id]||{})]));}
function reviewDetail(r:ProjectInput,id:ReviewSection){const q=r.quadri!;if(id==='clima')return 'Exterior: verano '+fmt(q.outdoorSummer.value,1)+' °C · invierno '+fmt(q.outdoorWinter.value,1)+' °C. Interior por ambiente. Revisá los datos climáticos y la variación diaria.';
 if(id==='envolvente'){const assumed=[...r.surfaces,...r.windows].filter(x=>!x.quadriMaterial&&['supuesto','heredado'].includes(x.u.provenance));return r.surfaces.length+' cerramientos · '+r.windows.length+' ventanas. '+(assumed.length?assumed.map(x=>x.name).join(', ')+': K supuesto o heredado; elegí material o confirmá el dato.':'Revisá materiales, áreas, orientaciones y protección solar.');}
 if(id==='internas')return fmt(r.internals.people.count.value,0)+' personas · '+fmt(r.internals.lights.installedPower.value,0)+' W de iluminación · '+fmt(r.internals.equipment.inputPower.value,0)+' W de equipos. Los ceros son válidos si confirmás que corresponden. En invierno no se descuentan ganancias internas.';
 return 'Ventilación '+(q.ventMode==='manual'?fmt(r.outdoorFlow.value)+' '+r.outdoorFlow.unit:fmt(q.outsidePct.value)+'% con mínimo por persona')+' · infiltración '+fmt(r.infiltrationACH.value)+' ACH. Revisá impulsión, conductos y suplementos de invierno.';}
function reviewDrawer(){checkpointRoom();drawer('Revisar carga del edificio','<p class="p-note">Confirmá cada bloque después de revisar sus valores. Si los cambiás, el bloque vuelve a quedar pendiente. Esto registra la revisión de entradas; la validación de resultados queda para la comparación final.</p>'+projectRooms().map(r=>'<section class="p-review-room"><h3>'+esc(r.room)+'</h3>'+reviewsFor(r).map(x=>'<article class="p-review-row"><div><strong>'+icon(x.reviewed?'circle-check':'circle-dashed')+' '+esc(x.name)+'</strong><small>'+esc(reviewDetail(r,x.id))+'</small></div><div class="p-actions">'+btn('Editar','data-review-edit="'+esc(r.id)+'" data-review-step="'+x.step+'"')+btn(x.reviewed?'Revisado':'Confirmar datos','data-confirm-review="'+x.id+'" data-review-id="'+esc(r.id)+'" '+(x.reviewed?'disabled':''),x.reviewed?'ghost':'primary')+'</div></article>').join('')+'</section>').join(''));
 app.querySelectorAll('[data-review-edit]').forEach(el=>(el as HTMLElement).onclick=()=>{state.step=Number((el as HTMLElement).dataset.reviewStep);activateRoom((el as HTMLElement).dataset.reviewEdit!);});
 app.querySelectorAll('[data-confirm-review]').forEach(el=>(el as HTMLElement).onclick=()=>{const id=(el as HTMLElement).dataset.reviewId!,section=(el as HTMLElement).dataset.confirmReview as ReviewSection,r=state.rooms.find(x=>x.id===id)!;try{calculateRoom(r);state.reviews[id]??={};state.reviews[id][section]=reviewSignature(r,section,projectPartitions().filter(p=>p.roomAId===id||p.roomBId===id));log('Datos revisados: '+r.room+' · '+REVIEW_SECTIONS.find(x=>x.id===section)!.name);store();render();reviewDrawer();}catch(e){toast('Corregí el ambiente antes de confirmar: '+(e as Error).message);}});
}
function exportProjectFile(){try{checkpointRoom();const building=buildingInput();calculateBuilding(building);download('THERMABOT-Quadri-proyecto-'+building.projectId+'.json',JSON.stringify({application:'THERMABOT-building',schemaVersion:1,date:new Date().toISOString(),building,reviews:projectReviews()},null,2),'application/json');toast('Archivo del proyecto descargado: todos los ambientes y ambas estaciones',true);}catch(e){toast('Corregí las entradas antes de exportar el proyecto: '+(e as Error).message);}}
function projectFileDrawer(){drawer('Guardar y recuperar el proyecto','<p class="p-note"><strong>'+esc(currentProject().name)+'</strong> · '+projectRooms().length+' ambientes. El borrador se guarda automáticamente en este navegador. Descargá un archivo para conservarlo fuera de esta computadora.</p><div class="p-review-room"><h3>Versión en este navegador</h3><p class="p-note">Conserva el edificio completo: geometría, materiales, ventanas, ambas estaciones y revisión de datos.</p>'+btn('Guardar versión del edificio','data-file-save','primary')+'</div><div class="p-review-room"><h3>Archivo para trasladar o recuperar</h3><div class="p-actions">'+btn('Descargar proyecto JSON','data-file-export','primary')+btn('Recuperar proyecto JSON','data-file-import')+'</div><p class="p-note">Al recuperar, se verifica el archivo y se avisa antes de reemplazar ambientes de un proyecto existente.</p></div><div class="p-review-room"><h3>Versiones de este proyecto</h3>'+savedRows(state.saved.filter(r=>r.input.projectId===state.input.projectId))+'</div>');
 (app.querySelector('[data-file-save]') as HTMLElement).onclick=()=>{const before=state.saved.length;saveCalculation();if(state.saved.length>before)projectFileDrawer();};(app.querySelector('[data-file-export]') as HTMLElement).onclick=exportProjectFile;(app.querySelector('[data-file-import]') as HTMLElement).onclick=()=>importJson(importBackup);app.querySelectorAll('[data-open-calc]').forEach(el=>(el as HTMLElement).onclick=()=>openSavedCalculation((el as HTMLElement).dataset.openCalc!));}
function bindLoadingTools(){app.querySelectorAll('[data-review-room]').forEach(el=>(el as HTMLElement).onclick=reviewDrawer);app.querySelectorAll('[data-project-file]').forEach(el=>(el as HTMLElement).onclick=projectFileDrawer);app.querySelectorAll('[data-season]').forEach(el=>(el as HTMLElement).onclick=()=>{const season=(el as HTMLElement).dataset.season as 'verano'|'invierno';if(state.input.quadri!.season===season)return;state.input.quadri!.season=season;shareQuadriClimate();recalc();render();scheduleStore();toast((season==='verano'?'Verano':'Invierno')+' aplicado a todos los ambientes. Se conservan ambas cargas de datos.',true);});}

document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search();}if(e.key==='Escape')closeLayer();});

const embedded=new URLSearchParams(location.search).has('embedded');
function trackingProjects(){try{const t=JSON.parse(localStorage.getItem('thermabot.tracker.v1')||'{}');return (t.projects||[]).map((p:any)=>({id:p.id,name:p.name,place:p.establishment||'',system:p.system||'',progress:Number(p.progress)||0,status:p.status||''}));}catch{return [];}}
function publishQuadri(record:any){if(!embedded)return;const list=JSON.parse(localStorage.getItem('thermabot.proyectos.v1')||'[]');const building=record.building;const calc=calculateBuilding(building);const p=state.projects.find(x=>x.id===state.input.projectId);const value={id:record.id,nombre:(p?.name||building.name)+' · '+state.input.quadri!.season,condiciones:{ciudad:state.input.quadri?.city||"Clima ingresado",tempExterior:state.input.climate.temperature[record.output.peak.hour].value,tempInterior:state.input.climate.indoorTemperature.value},ambientes:building.rooms.map((r:any)=>({id:r.id,nombre:r.room})),method:'quadri-v3',quadri:record,summary:{total_kw:calc.peak.total/1000,peakHour:calc.peak.hour,area:calc.area}};list.unshift(value);localStorage.setItem('thermabot.proyectos.v1',JSON.stringify(list));parent.postMessage({type:'thermabot:saved',balanceId:record.id,projectId:state.input.projectId,explicit:true},location.origin);}
if(embedded){const projects=trackingProjects();state.projects=projects.length?projects:[{id:'sin-asignar',name:'Balance sin proyecto',place:'',system:'',progress:0,status:'Borrador'}];state.tasks=[];const params=new URLSearchParams(location.search);const candidate=params.get('projectId')||state.projectId;const requested=state.projects.some((p:any)=>p.id===candidate)?candidate:state.projects[0].id;if(requested&&state.projects.some((p:any)=>p.id===requested)){state.projectId=requested;const room=state.rooms.find(r=>r.projectId===requested);if(room)state.input=room;else{const template=clone(state.input);template.projectId=requested;state.input=enableQuadri(createRoom(template,crypto.randomUUID(),'Ambiente 1',5,4,2.8));state.rooms.push(state.input);}}const id=params.get('balanceId');if(id){const saved=state.saved.find(r=>r.id===id);if(saved){if(saved.building){state.rooms=state.rooms.filter(r=>r.projectId!==saved.building!.projectId).concat(saved.building.rooms.map(r=>enableQuadri(migrateEnvelope(clone(r)))));state.partitions=state.partitions.filter(p=>p.projectId!==saved.building!.projectId).concat(clone(saved.building.partitions||[]));}state.input=state.rooms.find(r=>r.id===saved.input.id)||clone(saved.input);state.projectId=state.input.projectId;if(saved.reviews)Object.assign(state.reviews,clone(saved.reviews));if(saved.water)state.waterResults[saved.input.projectId]=clone(saved.water);}}state.route='Balance térmico';document.documentElement.classList.add('embedded');}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent)return;const msg=e.data;if(msg?.type==='thermabot:save'){if(!msg.projectId){toast('Seleccioná un proyecto de seguimiento antes de guardar.');return;}state.projects=trackingProjects();if(state.input.projectId!==msg.projectId){state.projectId=msg.projectId;openProjectRooms(msg.projectId);}saveCalculation();}if(msg?.type==='thermabot:print')generatePDF();if(msg?.type==='thermabot:theme'){state.appearance=msg.theme==='dark'?'dark':'light';applyAppearance();}});

shell();recalc();render();if(embedded)parent.postMessage({type:'thermabot:ready',balanceId:state.saved.find(r=>r.input.projectId===state.input.projectId)?.id||null},location.origin);
if(storageFailure)toast(storageFailure);
